'use client';

import { useEffect, useRef, useState } from 'react';
import { parseGIF, decompressFrames } from 'gifuct-js';

const gifBase64 = 'data:image/gif;base64,';

export default function HomePage() {
  const [showJumpscare, setShowJumpscare] = useState(false);
  const [showUnsavedWarning, setShowUnsavedWarning] = useState(false);
  const hasUnsavedChanges = useRef(false);
  const videoRef = useRef(null);

  useEffect(() => {
    const handleBeforeUnload = (event) => {
      if (!hasUnsavedChanges.current) return;

      event.preventDefault();
      event.returnValue = '';
    };

    window.addEventListener('beforeunload', handleBeforeUnload);

    let stopped = false;

    const playGifInConsole = async () => {
      try {
        const response = await fetch(gifBase64);
        const buffer = await response.arrayBuffer();

        const gif = parseGIF(buffer);
        const frames = decompressFrames(gif, true);

        if (!frames.length) return;

        const width = gif.lsd.width;
        const height = gif.lsd.height;

        const canvas = document.createElement('canvas');
        canvas.width = width;
        canvas.height = height;

        const ctx = canvas.getContext('2d');

        ctx.clearRect(0, 0, width, height);

        while (!stopped) {
          for (const frame of frames) {
            if (stopped) break;

            const imageData = new ImageData(
              new Uint8ClampedArray(frame.patch),
              frame.dims.width,
              frame.dims.height
            );

            ctx.putImageData(
              imageData,
              frame.dims.left,
              frame.dims.top
            );

            const frameImage = canvas.toDataURL('image/png');

            console.log(
              '%c ',
              `
                display: inline-block;
                width: ${width}px;
                height: ${height}px;
                padding: 0;
                margin: 0;
                background-image: url("${frameImage}");
                background-size: contain;
                background-repeat: no-repeat;
                background-position: center;
                font-size: 1px;
                line-height: 1px;
              `
            );

            const delay = Math.max(
              Number(frame.delay || 10) * 10,
              20
            );

            await new Promise((resolve) => {
              setTimeout(resolve, delay);
            });
          }
        }
      } catch (error) {
        console.error('GIF error:', error);
      }
    };

    playGifInConsole();

    return () => {
      stopped = true;
      window.removeEventListener('beforeunload', handleBeforeUnload);
    };
  }, []);

  async function triggerJumpscare() {
    hasUnsavedChanges.current = true;
    setShowJumpscare(true);

    try {
      await document.documentElement.requestFullscreen();
    } catch {}

    if (videoRef.current) {
      videoRef.current.currentTime = 0;
      videoRef.current.play().catch(() => {});
    }
  }

  return (
    <main>
      <form
        onInput={() => {
          hasUnsavedChanges.current = true;
        }}
      >
        <h1>
          Hello, Cocainee.pro uses cookies please accept them to continue
        </h1>

        <nav>
          <a href="#privacy">Privacy Policy</a>
          <a href="#terms">Terms of Service</a>
        </nav>

        <label className="form-option">
          <input
            type="checkbox"
            name="remember-choice"
          />
          Remember my choice
        </label>

        <div>
          <button
            type="button"
            onClick={triggerJumpscare}
          >
            Accept
          </button>

          <button
            type="button"
            onClick={triggerJumpscare}
          >
            Decline
          </button>
        </div>
      </form>

      <div
        className={showJumpscare ? 'jumpscare visible' : 'jumpscare'}
        role="dialog"
        aria-label="Jumpscare"
        aria-hidden={!showJumpscare}
      >
        <video
          ref={videoRef}
          src="/cdn/video.mp4"
          autoPlay
          playsInline
          preload="auto"
        />

        {showUnsavedWarning && (
          <div
            className="unsaved-dialog"
            role="alertdialog"
            aria-modal="true"
            aria-labelledby="unsaved-title"
          >
            <h2 id="unsaved-title">
              Unsaved changes
            </h2>

            <p>
              This document has changes that have not been saved.
            </p>

            <div className="dialog-actions">
              <button
                type="button"
                onClick={() => setShowUnsavedWarning(false)}
              >
                Cancel
              </button>

              <button
                type="button"
                onClick={() => {
                  setShowUnsavedWarning(false);
                  setShowJumpscare(false);
                }}
              >
                Close without saving
              </button>
            </div>
          </div>
        )}
      </div>
    </main>
  );
}
